import 'dart:io';
import 'dart:ui' show Locale;

import 'package:flutter_test/flutter_test.dart';
import 'package:toomu/app/core/utils/subtitles.dart';
import 'package:youtube_explode_dart/youtube_explode_dart.dart';

ClosedCaptionTrackInfo track(String code, {bool auto = false, ClosedCaptionFormat format = ClosedCaptionFormat.srv3}) =>
    ClosedCaptionTrackInfo.fromJson({
      'url': 'https://www.youtube.com/api/timedtext?lang=$code&fmt=${format.formatCode}',
      'language': {'code': code, 'name': code},
      'isAutoGenerated': auto,
      'format': {'formatCode': format.formatCode},
    });

ClosedCaption cue(String text, int fromMs, int lengthMs) =>
    ClosedCaption(text, Duration(milliseconds: fromMs), Duration(milliseconds: lengthMs), const []);

void main() {
  group('which subtitles are saved', () {
    test('the phone\'s language and English, without duplicates', () {
      expect(Subtitles.wanted(const Locale('bn', 'BD')), ['bn', 'en']);
      expect(Subtitles.wanted(const Locale('en', 'US')), ['en']);
    });

    test('uploaded subtitles win over auto-generated ones of the same language', () {
      final picked = Subtitles.pick([track('en', auto: true), track('en-GB'), track('fr')], ['en']);
      expect(picked.single.language.code, 'en-GB');
      expect(picked.single.isAutoGenerated, isFalse);
    });

    test('auto-generated subtitles are used when nobody uploaded any', () {
      final picked = Subtitles.pick([track('en', auto: true)], ['en']);
      expect(picked.single.isAutoGenerated, isTrue);
    });

    test('one track per wanted language, in order; missing languages skipped', () {
      final picked = Subtitles.pick([track('en'), track('bn'), track('de')], ['bn', 'hi', 'en']);
      expect(picked.map((t) => t.language.code), ['bn', 'en']);
    });

    test('only the parsable srv3 copy of a track is fetched', () {
      final picked = Subtitles.pick(
        [for (final f in ClosedCaptionFormat.values) track('en', format: f)],
        ['en'],
      );
      expect(picked.single.format.formatCode, 'srv3');
    });

    test('"en" does not match languages that only start with the same letters', () {
      expect(Subtitles.pick([track('eno')], ['en']), isEmpty);
    });

    test('watching: none in the wanted languages still offers what the video has, uploaded first', () {
      final picked = Subtitles.forWatching([track('bn', auto: true), track('ja')], ['en']);
      expect(picked.single.language.code, 'ja');
      expect(Subtitles.forWatching([track('bn', auto: true)], ['en']).single.language.code, 'bn');
      expect(Subtitles.forWatching([track('en'), track('ja')], ['en']).map((t) => t.language.code), ['en']);
      expect(Subtitles.forWatching(const [], ['en']), isEmpty);
    });
  });

  group('SRT', () {
    test('numbered cues with hh:mm:ss,mmm times', () {
      final srt = Subtitles.srt([cue('Hello', 1500, 2000), cue('World', 3723004, 1000)]);
      expect(
        srt,
        '1\n00:00:01,500 --> 00:00:03,500\nHello\n\n'
        '2\n01:02:03,004 --> 01:02:04,004\nWorld\n\n',
      );
    });

    test('blank cues are dropped without leaving a gap in the numbering', () {
      final srt = Subtitles.srt([cue('  ', 0, 500), cue('a\r\nb', 1000, 500), cue('c', 2000, 500)]);
      expect(srt, startsWith('1\n00:00:01,000 --> 00:00:01,500\na\nb\n\n2\n'));
    });
  });

  group('subtitle tracks from a web page', () {
    test('subtitles and captions with a usable link, one per language', () {
      final subs = Subtitles.fromTracks([
        {'url': 'https://x.com/en.vtt', 'lang': 'en', 'kind': 'subtitles'},
        {'url': 'https://x.com/fr.srt', 'lang': 'fr-CA', 'kind': 'captions'},
        {'url': 'https://x.com/en-sdh.vtt', 'lang': 'en', 'kind': 'captions'},
        {'url': 'https://x.com/chapters.vtt', 'lang': 'de', 'kind': 'chapters'},
        {'url': 'https://x.com/meta.vtt', 'lang': 'es', 'kind': 'metadata'},
        {'url': 'blob:https://x.com/123', 'lang': 'it'},
        {'url': 'https://x.com/odd.vtt', 'lang': 'English'},
        {'url': 'https://x.com/none.vtt'},
      ]);
      expect(subs, {'en': 'https://x.com/en.vtt', 'fr-CA': 'https://x.com/fr.srt', 'und': 'https://x.com/odd.vtt'});
    });

    test('a track with no kind counts as subtitles (HTML default)', () {
      expect(Subtitles.fromTracks([{'url': 'https://x.com/a.vtt', 'lang': 'en'}]), {'en': 'https://x.com/a.vtt'});
    });

    test('anything that is not a list of tracks gives none', () {
      expect(Subtitles.fromTracks(null), isEmpty);
      expect(Subtitles.fromTracks('x'), isEmpty);
      expect(Subtitles.fromTracks([1, null, {'url': 3}]), isEmpty);
    });

    test('only real subtitle text is saved, not an error or login page', () {
      expect(Subtitles.looksLikeSubtitles('WEBVTT\n\n00:01.000 --> 00:02.000\nHi'), isTrue);
      expect(Subtitles.looksLikeSubtitles('1\n00:00:01,000 --> 00:00:02,000\nHi'), isTrue);
      expect(Subtitles.looksLikeSubtitles('[Script Info]\nTitle: x'), isTrue);
      expect(Subtitles.looksLikeSubtitles('<!DOCTYPE html><html>Access denied</html>'), isFalse);
      expect(Subtitles.looksLikeSubtitles(''), isFalse);
    });

    test('the file keeps the subtitle format of its link, WebVTT when unknown', () {
      expect(Subtitles.extOf('https://x.com/a/en.SRT?token=1'), 'srt');
      expect(Subtitles.extOf('https://x.com/a/en.vtt'), 'vtt');
      expect(Subtitles.extOf('https://x.com/a/en.ass'), 'ass');
      expect(Subtitles.extOf('https://x.com/subtitle?id=5'), 'vtt');
      expect(Subtitles.extOf('https://x.com/a.php'), 'vtt');
    });
  });

  group('sidecar files', () {
    late Directory dir;
    setUp(() => dir = Directory.systemTemp.createTempSync('subs'));
    tearDown(() => dir.deleteSync(recursive: true));

    String touch(String name) => (File('${dir.path}/$name')..writeAsStringSync('x')).path;

    test('saved next to the video as <name>.<lang>.srt', () {
      expect(Subtitles.sidecarPath('/x/Mr. Bean (1080p).mp4', 'en-GB'), '/x/Mr. Bean (1080p).en-GB.srt');
      expect(Subtitles.sidecarPath('/x/Clip.mp4', 'und', 'vtt'), '/x/Clip.und.vtt');
    });

    test('the video\'s subtitle files are found, other videos\' are not', () {
      final video = touch('Mr. Bean.mp4');
      final mine = [touch('Mr. Bean.en.srt'), touch('Mr. Bean.srt'), touch('Mr. Bean.pt-BR.vtt')];
      touch('Mr. Bean.ep2.en.srt');
      touch('Mr. Bean 2.en.srt');
      touch('Mr. Bean.en.txt');
      touch('Mr. Bean.jpg');
      expect(Subtitles.sidecarsOf(video), unorderedEquals(mine));
    });

    test('a saved file is found again by the player', () {
      final video = touch('Clip.mp4');
      File(Subtitles.sidecarPath(video, 'bn')).writeAsStringSync('1');
      expect(Subtitles.sidecarsOf(video), [Subtitles.sidecarPath(video, 'bn')]);
    });

    test('a missing folder finds nothing instead of throwing', () {
      expect(Subtitles.sidecarsOf('${dir.path}/gone/Clip.mp4'), isEmpty);
    });
  });
}
